/**
 * ALE-447: the Intake page's payment orchestration, one actor per Intake
 * page instance (`useMachine`; never a module-scope actor).
 *
 * The phase follows Phoenix's safe view (`page.action` and `page.state`),
 * which the host sends as `PAGE` whenever the load data changes; the machine
 * never infers a payment outcome itself.
 *
 * - `payment`: opening the link starts payment automatically, once per
 *   instance, as the browser POST that takes the Seat Hold. The start waits
 *   for `MOUNTED`, which the host sends only from the mounted browser, so a
 *   server render or prefetch of the page's GET never reserves a place. Phoenix resumes a live hold's session rather than creating
 *   another. A refusal shows Phoenix's detail, an unexpected failure fixed
 *   copy, and both offer a manual retry. If Phoenix's view returns to a
 *   payment action after the automatic start was spent, the person starts
 *   again by hand (`paused`); the page never POSTs twice on its own.
 *   `checkout` hands the session to the embedded widget, whose own machine
 *   owns collection and confirmation.
 * - `confirmPlace`: a Carried Fee holder confirms instead of paying. The
 *   remote form owns that submission; this phase only selects it.
 * - `awaitingPayment`: `payment_in_progress` asks Phoenix again after
 *   `refreshMs`, re-armed by every new view, until it reports another state.
 * - `settled`: every other view; its one action (Check again) asks Phoenix.
 */
import type { BeginnersIntakePage } from "@dhc/api-client";
import { assign, fromPromise, setup, type SnapshotFrom } from "xstate";
import {
	confirmsWithCarriedFee,
	startsCheckout,
} from "#lib/beginners-workshops/intake-page.js";

/** What the start-payment POST answers; `undefined` while it redirects away. */
export type IntakePaymentStart =
	| { ok: true; clientSecret: string; sessionId: string }
	| { ok: false; error: string }
	| undefined;

export type IntakeCheckoutSession = { clientSecret: string; sessionId: string };

export type IntakePageInput = { page: BeginnersIntakePage; refreshMs: number };

export type IntakePageContext = IntakePageInput & {
	/** Whether the host component is mounted in the browser. */
	mounted: boolean;
	/** Whether this instance has spent its one automatic start. */
	started: boolean;
	session: IntakeCheckoutSession | null;
	/** Why the last start did not open payment, worded for the person. */
	refusal: string | null;
};

export type IntakePageEvent =
	| { type: "MOUNTED" }
	| { type: "PAGE"; page: BeginnersIntakePage }
	| { type: "RETRY" }
	| { type: "REFRESH" };

export const START_FAILED =
	"Payment is unavailable right now. Please try again shortly.";

export const intakePageMachine = setup({
	// SAFETY: `setup({ types })` reads only the types of these placeholders.
	types: {
		context: {} as IntakePageContext,
		events: {} as IntakePageEvent,
		input: {} as IntakePageInput,
	},
	actors: {
		startPayment: fromPromise<IntakePaymentStart, void>(async () => {
			throw new Error("startPayment must be provided by the host");
		}),
	},
	actions: {
		refresh: () => {},
		adoptPage: assign({
			page: ({ context, event }) =>
				event.type === "PAGE" ? event.page : context.page,
		}),
	},
	guards: {
		newPage: ({ context, event }) =>
			event.type === "PAGE" && event.page !== context.page,
		newPageStillPays: ({ context, event }) =>
			event.type === "PAGE" &&
			event.page !== context.page &&
			startsCheckout(event.page),
		pays: ({ context }) => startsCheckout(context.page),
		startSpent: ({ context }) => context.started,
		mounted: ({ context }) => context.mounted,
		confirms: ({ context }) => confirmsWithCarriedFee(context.page),
		paymentInProgress: ({ context }) =>
			context.page.state === "payment_in_progress",
	},
	delays: {
		refreshDelay: ({ context }) => context.refreshMs,
	},
}).createMachine({
	id: "intakePage",
	context: ({ input }) => ({
		...input,
		mounted: false,
		started: false,
		session: null,
		refusal: null,
	}),
	initial: "routing",
	on: {
		MOUNTED: { actions: assign({ mounted: true }) },
		PAGE: { guard: "newPage", target: ".routing", actions: "adoptPage" },
	},
	states: {
		routing: {
			always: [
				{ guard: "pays", target: "payment" },
				{ guard: "confirms", target: "confirmPlace" },
				{ guard: "paymentInProgress", target: "awaitingPayment" },
				{ target: "settled" },
			],
		},
		payment: {
			// A fresh view that still pays (a live hold after the POST) keeps
			// the session and the widget where they are.
			on: {
				PAGE: [
					{ guard: "newPageStillPays", actions: "adoptPage" },
					{ guard: "newPage", target: "routing", actions: "adoptPage" },
				],
			},
			initial: "deciding",
			states: {
				deciding: {
					always: [
						{ guard: "startSpent", target: "paused" },
						{ guard: "mounted", target: "starting" },
						{ target: "waitingForBrowser" },
					],
				},
				waitingForBrowser: {
					on: {
						MOUNTED: {
							target: "starting",
							actions: assign({ mounted: true }),
						},
					},
				},
				starting: {
					entry: assign({ started: true }),
					invoke: {
						src: "startPayment",
						onDone: [
							{
								guard: ({ event }) => event.output?.ok === true,
								target: "checkout",
								actions: assign({
									session: ({ event }) =>
										event.output?.ok
											? {
													clientSecret: event.output.clientSecret,
													sessionId: event.output.sessionId,
												}
											: null,
									refusal: null,
								}),
							},
							{
								guard: ({ event }) => event.output?.ok === false,
								target: "refused",
								actions: assign({
									refusal: ({ event }) =>
										event.output?.ok === false ? event.output.error : null,
								}),
							},
							// A hold created before the embedded migration is
							// redirected to hosted Checkout; the page is leaving.
							{ target: "redirecting" },
						],
						onError: {
							target: "refused",
							actions: assign({ refusal: START_FAILED }),
						},
					},
				},
				checkout: {},
				refused: { on: { RETRY: { target: "starting" } } },
				paused: { on: { RETRY: { target: "starting" } } },
				redirecting: {},
			},
		},
		confirmPlace: {},
		awaitingPayment: {
			on: { REFRESH: { actions: "refresh" } },
			after: { refreshDelay: { guard: "mounted", actions: "refresh" } },
		},
		settled: {
			on: { REFRESH: { actions: "refresh" } },
		},
	},
});

export type IntakePagePhase =
	| "waitingForBrowser"
	| "starting"
	| "checkout"
	| "refused"
	| "paused"
	| "redirecting"
	| "confirmPlace"
	| "awaitingPayment"
	| "settled";

/** The leaf phase of a snapshot of `intakePageMachine`. */
export function intakePagePhase(
	snapshot: SnapshotFrom<typeof intakePageMachine>,
): IntakePagePhase {
	for (const phase of [
		"waitingForBrowser",
		"starting",
		"checkout",
		"refused",
		"paused",
		"redirecting",
	] as const) {
		if (snapshot.matches({ payment: phase })) return phase;
	}
	if (snapshot.matches("confirmPlace")) return "confirmPlace";
	if (snapshot.matches("awaitingPayment")) return "awaitingPayment";
	// `routing` and `payment.deciding` are transient and never observed.
	return "settled";
}
<!--
	ALE-381: the person's Intake page. Everything shown is Phoenix's safe
	view; the one action is Phoenix's too. ALE-447: `intakePageMachine` owns
	the orchestration — the automatic payment start, refusal and retry, the
	payment-in-progress refresh and the Carried Fee confirm alternative
	(ALE-388) — and the embedded widget owns collection and confirmation. The
	remote forms stay the transport. No self-service decline or withdraw:
	replies to the email go through a coordinator.
-->
<script lang="ts">
import { onMount, tick, untrack } from "svelte";
import type { BeginnersIntakePage } from "@dhc/api-client";
import { CalendarDays, Clock, MapPin, RefreshCw } from "@lucide/svelte";
import { useMachine } from "@xstate/svelte";
import { fromPromise } from "xstate";
import { goto, invalidateAll } from "$app/navigation";
import IntakeCheckout from "#lib/components/beginners-workshops/intake-checkout.svelte";
import { formatDublinInstant } from "#lib/club-calendar.js";
import {
	intakeActionLabel,
	intakeCopy,
	intakeDetails,
	REFRESH_MS,
} from "#lib/beginners-workshops/intake-page.js";
import {
	intakePageMachine,
	intakePagePhase,
	type IntakePaymentStart,
} from "#lib/beginners-workshops/intake-page-machine.js";
import * as Alert from "#lib/components/ui/alert/index.js";
import { Badge } from "#lib/components/ui/badge/index.js";
import { Button } from "#lib/components/ui/button/index.js";
import * as Card from "#lib/components/ui/card/index.js";
import { confirmIntakePlace, startIntakePayment } from "./intake.remote";

let {
	page,
	token,
	refresh = () => void invalidateAll(),
	refreshMs = REFRESH_MS,
	startPayment = submitPayment,
}: {
	page: BeginnersIntakePage;
	token: string;
	refresh?: () => void;
	refreshMs?: number;
	startPayment?: () => Promise<IntakePaymentStart>;
} = $props();

const formId = $props.id();
const paymentForm = startIntakePayment.for(formId);
const confirmForm = confirmIntakePlace.for(formId);

// The POST that takes the Seat Hold; `result` is undefined while a hosted
// hold from before the embedded migration redirects away.
async function submitPayment(): Promise<IntakePaymentStart> {
	await tick(); // The remote form must be attached before programmatic submit.
	if (!(await paymentForm.submit())) throw new Error("Payment not submitted");
	return paymentForm.result;
}

// Inputs are fixed for this instance; the route remounts it per token, and
// later views arrive as `PAGE`.
const { snapshot, send } = useMachine(
	intakePageMachine.provide({
		actors: {
			startPayment: fromPromise(() => untrack(() => startPayment)()),
		},
		actions: { refresh: () => untrack(() => refresh)() },
	}),
	{ input: untrack(() => ({ page, refreshMs })) },
);

// Only the mounted browser may start a payment.
onMount(() => send({ type: "MOUNTED" }));
$effect(() => {
	send({ type: "PAGE", page });
});

const phase = $derived(intakePagePhase($snapshot));
const session = $derived($snapshot.context.session);
const copy = $derived(intakeCopy(page));
const details = $derived(intakeDetails(page));
const actionLabel = $derived(intakeActionLabel(page));
const inPayment = $derived(
	phase === "waitingForBrowser" ||
		phase === "starting" ||
		phase === "checkout" ||
		phase === "refused" ||
		phase === "paused" ||
		phase === "redirecting",
);
const refusal = $derived.by(() => {
	if (phase === "confirmPlace") {
		const result = confirmForm.result;
		return result && !result.ok ? result.error : null;
	}
	return inPayment ? $snapshot.context.refusal : null;
});
// A retry keeps the earlier refusal on screen while it runs, like the
// button that sent it.
const retryLabel = $derived(
	phase === "refused" ? "Try again" : phase === "paused" ? actionLabel : null,
);
const retrying = $derived(phase === "starting" && !!refusal);
</script>

<Card.Root class="w-full max-w-lg" data-state={page.state}>
	<Card.Header>
		{#if details?.greeting}
			<p class="text-sm text-muted-foreground">{details.greeting}</p>
		{/if}
		<Card.Title>
			<h1 class="font-heading text-2xl leading-tight">{copy.title}</h1>
		</Card.Title>
		<Card.Description>{copy.body}</Card.Description>
	</Card.Header>

	{#if details}
		<Card.Content class="flex flex-col gap-3">
			<ul class="flex flex-col gap-2 text-sm" aria-label="Workshop">
				<li class="flex items-center gap-2">
					<CalendarDays class="size-4 text-muted-foreground" />{details.date}
				</li>
				<li class="flex items-center gap-2">
					<Clock class="size-4 text-muted-foreground" />{details.time}
				</li>
				<li class="flex items-center gap-2">
					<MapPin class="size-4 text-muted-foreground" />{details.venue}
				</li>
			</ul>
			{#if details.fee}
				<p class="flex items-center gap-2 text-sm">
					Fee <Badge variant={page.state === "paid" ? "secondary" : "outline"}
						>{details.fee}{page.state === "paid" ? " · paid" : ""}</Badge
					>
				</p>
			{/if}
			{#if refusal}
				<Alert.Root variant="destructive">
					<Alert.Description>{refusal}</Alert.Description>
				</Alert.Root>
			{/if}
		</Card.Content>
	{/if}

	{#if actionLabel}
		{#if page.action === "pay" && page.paymentCutoff}
			<Card.Content>
				<p class="text-sm text-muted-foreground">
					Payment deadline: {formatDublinInstant(page.paymentCutoff)}
				</p>
			</Card.Content>
		{/if}
		<Card.Footer>
			{#if inPayment}
				{#if phase === "checkout" && session}
					{#key session.clientSecret}
						<IntakeCheckout
							clientSecret=REDACTED
							onComplete={() =>
								goto(`?session_id=${encodeURIComponent(session.sessionId)}`)}
						/>
					{/key}
				{:else if phase === "waitingForBrowser" || phase === "redirecting" || (phase === "starting" && !retrying)}
					<p role="status" class="py-4 text-sm text-muted-foreground">
						Loading secure payment…
					</p>
				{/if}
				<form {...paymentForm} class="w-full" hidden={!retryLabel && !retrying}>
					<input {...paymentForm.fields.token.as("hidden", token)} />
					<Button
						type="button"
						class="w-full"
						disabled={retrying}
						aria-busy={retrying}
						onclick={() => send({ type: "RETRY" })}
					>
						{retrying ? "Loading secure payment…" : retryLabel}
					</Button>
				</form>
			{:else if phase === "confirmPlace"}
				<form {...confirmForm} class="w-full">
					<input {...confirmForm.fields.token.as("hidden", token)} />
					<Button type="submit" class="w-full" disabled={!!confirmForm.pending}>
						{actionLabel}
					</Button>
				</form>
			{:else}
				<Button
					variant="outline"
					class="w-full"
					onclick={() => send({ type: "REFRESH" })}
					aria-busy={page.state === "payment_in_progress"}
				>
					<RefreshCw
						class={page.state === "payment_in_progress" ? "animate-spin" : ""}
					/>
					{actionLabel}
				</Button>
			{/if}
		</Card.Footer>
	{/if}
</Card.Root>

