				</li>
			</ul>
			{#if details.fee}
				<p class="flex items-center gap-2 text-sm">
					Fee <Badge variant={page.state === "paid" ? "secondary" : "outline"}
						>{details.fee}{page.state === "paid" ? " · paid" : ""}</Badge
					>
				</p>
			{/if}
			{#if refusal}
				<Alert.Root variant="destructive">
					<Alert.Description>{refusal}</Alert.Description>
				</Alert.Root>
			{/if}
		</Card.Content>
	{/if}

	{#if actionLabel}
		{#if page.action === "pay" && page.paymentCutoff}
			<Card.Content>
				<p class="text-sm text-muted-foreground">
					Payment deadline: {formatDublinInstant(page.paymentCutoff)}
				</p>
			</Card.Content>
		{/if}
		<Card.Footer>
			{#if inPayment}
				{#if phase === "checkout" && session}
					{#key session.clientSecret}
						<IntakeCheckout
							clientSecret=REDACTED
							onComplete={() =>
								goto(`?session_id=${encodeURIComponent(session.sessionId)}`)}
						/>
					{/key}
				{:else if phase === "waitingForBrowser" || phase === "redirecting" || (phase === "starting" && !retrying)}
					<p role="status" class="py-4 text-sm text-muted-foreground">
						Loading secure payment…
					</p>
				{/if}
				<form {...paymentForm} class="w-full" hidden={!retryLabel && !retrying}>
					<input {...paymentForm.fields.token.as("hidden", token)} />
					<Button
						type="button"
						class="w-full"
						disabled={retrying}
						aria-busy={retrying}
						onclick={() => send({ type: "RETRY" })}
					>
						{retrying ? "Loading secure payment…" : retryLabel}
					</Button>
				</form>
			{:else if phase === "confirmPlace"}
				<form {...confirmForm} class="w-full">
					<input {...confirmForm.fields.token.as("hidden", token)} />
					<Button type="submit" class="w-full" disabled={!!confirmForm.pending}>
						{actionLabel}
					</Button>
				</form>
			{:else}
				<Button
					variant="outline"
					class="w-full"
					onclick={() => send({ type: "REFRESH" })}
					aria-busy={page.state === "payment_in_progress"}
				>
					<RefreshCw
						class={page.state === "payment_in_progress" ? "animate-spin" : ""}
					/>
					{actionLabel}
				</Button>
			{/if}
		</Card.Footer>
	{/if}
</Card.Root>

